from rest_framework.routers import DefaultRouter
from .views import EntityTypeViewSet,EntityFieldViewSet,LocationViewSet,RawCaptureViewSet,ExtractedRecordViewSet,DedupCandidateViewSet,ReviewTaskViewSet,AuditEventViewSet,RecordObservationViewSet,RecordChangeViewSet,PharmacyViewSet,MarketObservationViewSet
router=DefaultRouter()
router.register("entity-types",EntityTypeViewSet,basename="entity-type"); router.register("fields",EntityFieldViewSet,basename="entity-field"); router.register("locations",LocationViewSet,basename="location"); router.register("raw",RawCaptureViewSet,basename="raw-capture"); router.register("records",ExtractedRecordViewSet,basename="record"); router.register("duplicates",DedupCandidateViewSet,basename="duplicate"); router.register("reviews",ReviewTaskViewSet,basename="review"); router.register("audit",AuditEventViewSet,basename="audit"); router.register("observations",RecordObservationViewSet,basename="observation"); router.register("changes",RecordChangeViewSet,basename="change"); router.register("pharmacies",PharmacyViewSet,basename="pharmacy"); router.register("market-observations",MarketObservationViewSet,basename="market-observation")
urlpatterns=router.urls
